import {GOJO_V2_META as META} from './gojo-v2-meta.js';
import {gojoPose} from '../characters/gojo.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
import {beginBottomDialogue} from './bottom-dialogue.js';
export function gojoSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=META[key];if(!im?.complete||!im.naturalWidth||!m)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(m.columns-1,col))*w,Math.max(0,Math.min(m.rows-1,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawGojoActor(ctx,images,d,f,hurt=false,override=null){let p=override||gojoPose(f,hurt);const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;
 if(c?.kind==='void'&&c.ownerUid===f.uid)p={row:11,frame:Math.min(5,Math.floor(c.elapsed/cinematicSteps(c)*6))};else if(a?.kind==='void'&&a.ownerUid===f.uid)p={row:a.phase==='warning'?11:12,frame:a.phase==='warning'?4:Math.min(5,Math.floor((d.tick-a.launch)/24))};
 if(f.state==='defeat')p={row:7,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};gojoSprite(ctx,images,f.introAge!=null?'gojo_v2_intro':'gojo_v2',p.row,p.frame,f.x,f.y,.86,0,f.face);}
export function drawGojoBack(ctx,images,d,clock=0){for(const f of d.fighters)if(f.id==='gojo'&&f.hp>0){if(f.introAge!=null){if(f.introAge>.3){ctx.save();ctx.globalAlpha=Math.min(.6,f.introAge,(2.5-f.introAge)*2);gojoSprite(ctx,images,'gojo_v2_intro_vfx',0,Math.min(5,Math.floor(f.introAge/2.5*6)),f.x,f.y-35,.6);ctx.restore();}}
 else{for(const z of f.gojoFields||[]){const age=(d.tick-z.born)/60;gojoSprite(ctx,images,'gojo_v2_vfx',0,Math.min(5,Math.floor(age/1.2*6)),z.x,z.y-20,.9,clock*.7);}
 if(f.state==='purple'&&f.age<1.15)gojoSprite(ctx,images,'gojo_v2_vfx',2,Math.min(3,Math.floor(f.age/1.15*4)),f.x+f.face*60,f.y-65,.6);if(f.state==='red'&&f.age<.65)gojoSprite(ctx,images,'gojo_v2_vfx',1,Math.min(2,Math.floor(f.age/.65*3)),f.x+f.face*45,f.y-60,.45);
 }}
 const a=d.personalUltimate?.attack;if(a?.kind==='void'){const im=images.gojo_v2_ultimate_vfx,m=META.gojo_v2_ultimate_vfx;if(a.phase==='warning'){ctx.save();ctx.strokeStyle='#8eefff';ctx.lineWidth=2;ctx.setLineDash([10,7]);ctx.beginPath();ctx.ellipse(a.targetX,a.targetY,190,140,0,0,Math.PI*2);ctx.stroke();ctx.restore();}else{ctx.save();ctx.translate(a.targetX,a.targetY);ctx.scale(1,.72);gojoSprite(ctx,images,'gojo_v2_ultimate_vfx',0,d.tick<a.launch+88?2+Math.floor(clock*6)%2:4,0,0,1.35,clock*.18);ctx.restore();}}}
export function drawGojoWorld(ctx,images,d,clock=0,reduced=false){for(const f of d.fighters)if(f.id==='gojo'&&f.hp>0&&d.tick<f.infinityUntil){ctx.save();ctx.globalAlpha=.7;ctx.strokeStyle='#a9f6ff';ctx.lineWidth=2;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(f.x,f.y-50,35+i*9,65+i*4,reduced?0:Math.sin(clock*5+i)*.2,0,Math.PI*2);ctx.stroke();}ctx.restore();}
 const a=d.personalUltimate?.attack;if(a?.kind==='void'&&a.phase==='travel'){gojoSprite(ctx,images,'gojo_v2_ultimate_vfx',1,Math.min(5,Math.floor((d.tick-a.launch)/20)),a.targetX,a.targetY-35,1.0);}}
export function drawGojoShot(ctx,images,s,x,y,clock){const red=s.kind==='gojored';gojoSprite(ctx,images,'gojo_v2_vfx',red?1:2,red?3:4,x,y,red?.55:.85,Math.atan2(s.vy,s.vx));}
export function drawGojoEffect(ctx,images,skill,frame,x,y,scale=1,angle=0){const row=skill==='blue'?0:skill==='red'?1:2;gojoSprite(ctx,images,'gojo_v2_vfx',row,frame,x,y,scale,angle);}
export function drawGojoChat(ctx,images,c,line='Domain Expansion: Unlimited Void.',reduced=false){const p=c.elapsed/cinematicSteps(c);beginBottomDialogue(ctx,'gojo');ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));gojoSprite(ctx,images,'gojo_v2_dialogue',p<.4?0:1,p<.4?1:0,480,280,.8);ctx.textAlign='left';ctx.fillStyle='#e7faff';ctx.font='bold 22px Georgia';const lines=line==='Domain Expansion: Unlimited Void.'?['Domain Expansion:','Unlimited Void.']:[line];for(const [i,t] of lines.entries())ctx.fillText(t,370,275+i*32,440);ctx.restore();}
export function drawGojoCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic;if(c?.kind==='void')drawGojoChat(ctx,images,c,undefined,reduced);}
